  2	<html lang="en">
  3	<head>
  4	<meta charset="UTF-8">
  5	<meta name="viewport" content="width=device-width, initial-scale=1.0">
  6	<title>Breakout</title>
  7	<style>
  8	  :root {
  9	    --bg: #0d1117;
 10	    --panel: #161b22;
 11	    --accent: #58a6ff;
 12	    --text: #c9d1d9;
 13	  }
 14	  * { margin: 0; padding: 0; box-sizing: border-box; }
 15	  body {
 16	    background: var(--bg);
 17	    color: var(--text);
 18	    font-family: "SF Mono", ui-monospace, Menlo, Consolas, monospace;
 19	    display: flex;
 20	    flex-direction: column;
 21	    align-items: center;
 22	    justify-content: center;
 23	    min-height: 100vh;
 24	    user-select: none;
 25	  }
 26	  #hud {
 27	    width: 800px;
 28	    max-width: 95vw;
 29	    display: flex;
 30	    justify-content: space-between;
 31	    padding: 10px 4px;
 32	    font-size: 14px;
 33	    letter-spacing: 1px;
 34	  }
 35	  #hud span b { color: var(--accent); }
 36	  canvas {
 37	    background: var(--panel);
 38	    border: 1px solid #30363d;
 39	    border-radius: 6px;
 40	    display: block;
 41	    max-width: 95vw;
 42	    height: auto;
 43	  }
 44	  #hint {
 45	    margin-top: 10px;
 46	    font-size: 12px;
 47	    color: #8b949e;
 48	    letter-spacing: 1px;
 49	  }
 50	</style>
 51	</head>
 52	<body>
 53	
 54	<div id="hud">
 55	  <span>SCORE <b id="score">0</b></span>
 56	  <span>LEVEL <b id="level">1</b></span>
 57	  <span>LIVES <b id="lives">3</b></span>
 58	</div>
 59	<canvas id="game" width="800" height="500"></canvas>
 60	<div id="hint">mouse or &larr; &rarr; to move &middot; space to launch / pause</div>
 61	
 62	<script>
 63	(() => {
 64	  "use strict";
 65	
 66	  const canvas = document.getElementById("game");
 67	  const ctx = canvas.getContext("2d");
 68	  const scoreEl = document.getElementById("score");
 69	  const levelEl = document.getElementById("level");
 70	  const livesEl = document.getElementById("lives");
 71	
 72	  const W = canvas.width;
 73	  const H = canvas.height;
 74	
 75	  // --- constants -----------------------------------------------------------
 76	  const PADDLE_W = 110;
 77	  const PADDLE_H = 14;
 78	  const PADDLE_Y = H - 34;
 79	  const PADDLE_SPEED = 620;          // px/s, keyboard
 80	  const BALL_R = 7;
 81	  const BALL_BASE_SPEED = 340;       // px/s
 82	  const BALL_SPEEDUP = 1.035;        // multiplier per paddle hit
 83	  const BALL_MAX_SPEED = 640;
 84	  const BRICK_COLS = 10;
 85	  const BRICK_ROWS = 6;
 86	  const BRICK_W = 68;
 87	  const BRICK_H = 22;
 88	  const BRICK_GAP = 6;
 89	  const BRICK_TOP = 70;
 90	  const BRICK_LEFT = (W - (BRICK_COLS * (BRICK_W + BRICK_GAP) - BRICK_GAP)) / 2;
 91	
 92	  const ROW_COLORS = ["#f85149", "#f0883e", "#d29922", "#3fb950", "#58a6ff", "#bc8cff"];
 93	
 94	  // --- state ----------------------------------------------------------------
 95	  const STATE = { READY: 0, PLAYING: 1, PAUSED: 2, GAME_OVER: 3, WIN: 4 };
 96	
 97	  let state = STATE.READY;
 98	  let score = 0;
 99	  let lives = 3;
100	  let level = 1;
101	
102	  const paddle = { x: W / 2 - PADDLE_W / 2, w: PADDLE_W };
103	  const ball = { x: 0, y: 0, vx: 0, vy: 0, speed: BALL_BASE_SPEED, stuck: true };
104	  let bricks = [];
105	  const keys = { left: false, right: false };
106	
107	  // --- bricks ----------------------------------------------------------------
108	  function buildBricks() {
109	    bricks = [];
110	    for (let r = 0; r < BRICK_ROWS; r++) {
111	      for (let c = 0; c < BRICK_COLS; c++) {
112	        bricks.push({
113	          x: BRICK_LEFT + c * (BRICK_W + BRICK_GAP),
114	          y: BRICK_TOP + r * (BRICK_H + BRICK_GAP),
115	          color: ROW_COLORS[r % ROW_COLORS.length],
116	          points: (BRICK_ROWS - r) * 10,
117	          alive: true,
118	        });
119	      }
120	    }
121	  }
122	
123	  function resetBall() {
124	    ball.stuck = true;
125	    ball.speed = BALL_BASE_SPEED;
126	    ball.x = paddle.x + PADDLE_W / 2;
127	    ball.y = PADDLE_Y - BALL_R - 1;
128	    ball.vx = 0;
129	    ball.vy = 0;
130	  }
131	
132	  function launchBall() {
133	    ball.stuck = false;
134	    // launch slightly off-vertical, alternating-ish angle
135	    const angle = (-Math.PI / 2) + (Math.random() * 0.6 - 0.3);
136	    ball.vx = Math.cos(angle) * ball.speed;
137	    ball.vy = Math.sin(angle) * ball.speed;
138	  }
139	
140	  function startLevel() {
141	    buildBricks();
142	    resetBall();
143	    state = STATE.READY;
144	  }
145	
146	  function newGame() {
147	    score = 0;
148	    lives = 3;
149	    level = 1;
150	    paddle.x = W / 2 - PADDLE_W / 2;
151	    startLevel();
152	    updateHud();
153	  }
154	
155	  function updateHud() {
156	    scoreEl.textContent = score;
157	    levelEl.textContent = level;
158	    livesEl.textContent = lives;
159	  }
160	
161	  // --- input -----------------------------------------------------------------
162	  canvas.addEventListener("mousemove", (e) => {
163	    const rect = canvas.getBoundingClientRect();
164	    const scale = W / rect.width;
165	    const mx = (e.clientX - rect.left) * scale;
166	    paddle.x = Math.min(Math.max(mx - PADDLE_W / 2, 0), W - PADDLE_W);
167	  });
168	
169	  window.addEventListener("keydown", (e) => {
170	    if (e.code === "ArrowLeft") keys.left = true;
171	    if (e.code === "ArrowRight") keys.right = true;
172	    if (e.code === "Space") {
173	      e.preventDefault();
174	      if (state === STATE.READY) {
175	        state = STATE.PLAYING;
176	        launchBall();
177	      } else if (state === STATE.PLAYING) {
178	        state = STATE.PAUSED;
179	      } else if (state === STATE.PAUSED) {
180	        state = STATE.PLAYING;
181	      } else if (state === STATE.GAME_OVER || state === STATE.WIN) {
182	        newGame();
183	      }
184	    }
185	  });
186	
187	  window.addEventListener("keyup", (e) => {
188	    if (e.code === "ArrowLeft") keys.left = false;
189	    if (e.code === "ArrowRight") keys.right = false;
190	  });
191	
192	  canvas.addEventListener("click", () => {
193	    if (state === STATE.READY) {
194	      state = STATE.PLAYING;
195	      launchBall();
196	    } else if (state === STATE.GAME_OVER || state === STATE.WIN) {
197	      newGame();
198	    }
199	  });
200	
201	  // --- physics ----------------------------------------------------------------
202	  function movePaddle(dt) {
203	    if (keys.left)  paddle.x -= PADDLE_SPEED * dt;
204	    if (keys.right) paddle.x += PADDLE_SPEED * dt;
205	    paddle.x = Math.min(Math.max(paddle.x, 0), W - PADDLE_W);
206	  }
207	
208	  function moveBall(dt) {
209	    if (ball.stuck) {
210	      ball.x = paddle.x + PADDLE_W / 2;
211	      ball.y = PADDLE_Y - BALL_R - 1;
212	      return;
213	    }
214	
215	    // sub-step so a fast ball can't tunnel through thin bricks
216	    const steps = Math.max(1, Math.ceil((ball.speed * dt) / (BALL_R * 0.8)));
217	    const sdt = dt / steps;
218	
219	    for (let i = 0; i < steps; i++) {
220	      ball.x += ball.vx * sdt;
221	      ball.y += ball.vy * sdt;
222	
223	      // walls
224	      if (ball.x - BALL_R < 0)       { ball.x = BALL_R;       ball.vx =  Math.abs(ball.vx); }
225	      if (ball.x + BALL_R > W)       { ball.x = W - BALL_R;   ball.vx = -Math.abs(ball.vx); }
226	      if (ball.y - BALL_R < 0)       { ball.y = BALL_R;       ball.vy =  Math.abs(ball.vy); }
227	
228	      // paddle
229	      if (ball.vy > 0 &&
230	          ball.y + BALL_R >= PADDLE_Y &&
231	          ball.y + BALL_R <= PADDLE_Y + PADDLE_H + 12 &&
232	          ball.x >= paddle.x - BALL_R &&
233	          ball.x <= paddle.x + PADDLE_W + BALL_R) {
234	
235	        // bounce angle depends on where the ball hits the paddle
236	        const hit = (ball.x - (paddle.x + PADDLE_W / 2)) / (PADDLE_W / 2); // -1..1
237	        const maxBounce = (5 * Math.PI) / 12; // 75 deg from vertical
238	        const angle = hit * maxBounce;
239	        ball.speed = Math.min(ball.speed * BALL_SPEEDUP, BALL_MAX_SPEED);
240	        ball.vx = Math.sin(angle) * ball.speed;
241	        ball.vy = -Math.cos(angle) * ball.speed;
242	        ball.y = PADDLE_Y - BALL_R;
243	      }
244	
245	      // bricks
246	      for (const b of bricks) {
247	        if (!b.alive) continue;
248	        if (ball.x + BALL_R < b.x || ball.x - BALL_R > b.x + BRICK_W ||
249	            ball.y + BALL_R < b.y || ball.y - BALL_R > b.y + BRICK_H) continue;
250	
251	        b.alive = false;
252	        score += b.points;
253	        updateHud();
254	
255	        // decide bounce axis by overlap depth
256	        const overlapX = Math.min(ball.x + BALL_R - b.x, b.x + BRICK_W - (ball.x - BALL_R));
257	        const overlapY = Math.min(ball.y + BALL_R - b.y, b.y + BRICK_H - (ball.y - BALL_R));
258	        if (overlapX < overlapY) ball.vx = -ball.vx;
259	        else ball.vy = -ball.vy;
260	        break; // one brick per sub-step
261	      }
262	
263	      // bottom
264	      if (ball.y - BALL_R > H) {
265	        loseLife();
266	        return;
267	      }
268	    }
269	  }
270	
271	  function loseLife() {
272	    lives--;
273	    updateHud();
274	    if (lives <= 0) {
275	      state = STATE.GAME_OVER;
276	    } else {
277	      resetBall();
278	      state = STATE.READY;
279	    }
280	  }
281	
282	  function checkLevelClear() {
283	    if (bricks.some(b => b.alive)) return;
284	    level++;
285	    if (level > 99) { level = 99; }
286	    startLevel();
287	    updateHud();
288	  }
289	
290	  // --- rendering ----------------------------------------------------------------
291	  function drawBricks() {
292	    for (const b of bricks) {
293	      if (!b.alive) continue;
294	      ctx.fillStyle = b.color;
295	      roundRect(b.x, b.y, BRICK_W, BRICK_H, 4);
296	      ctx.fill();
297	      // top highlight
298	      ctx.fillStyle = "rgba(255,255,255,0.18)";
299	      roundRect(b.x, b.y, BRICK_W, BRICK_H / 2, 4);
300	      ctx.fill();
301	    }
302	  }
303	
304	  function roundRect(x, y, w, h, r) {
305	    ctx.beginPath();
306	    ctx.moveTo(x + r, y);
307	    ctx.arcTo(x + w, y, x + w, y + h, r);
308	    ctx.arcTo(x + w, y + h, x, y + h, r);
309	    ctx.arcTo(x, y + h, x, y, r);
310	    ctx.arcTo(x, y, x + w, y, r);
311	    ctx.closePath();
312	  }
313	
314	  function drawPaddle() {
315	    ctx.fillStyle = "#e6edf3";
316	    roundRect(paddle.x, PADDLE_Y, PADDLE_W, PADDLE_H, 7);
317	    ctx.fill();
318	  }
319	
320	  function drawBall() {
321	    ctx.beginPath();
322	    ctx.arc(ball.x, ball.y, BALL_R, 0, Math.PI * 2);
323	    ctx.fillStyle = "#ffffff";
324	    ctx.fill();
325	  }
326	
327	  function drawOverlay(title, subtitle) {
328	    ctx.fillStyle = "rgba(13, 17, 23, 0.72)";
329	    ctx.fillRect(0, 0, W, H);
330	    ctx.textAlign = "center";
331	    ctx.fillStyle = "#e6edf3";
332	    ctx.font = "bold 42px 'SF Mono', ui-monospace, monospace";
333	    ctx.fillText(title, W / 2, H / 2 - 14);
334	    ctx.fillStyle = "#8b949e";
335	    ctx.font = "15px 'SF Mono', ui-monospace, monospace";
336	    ctx.fillText(subtitle, W / 2, H / 2 + 26);
337	  }
338	
339	  function render() {
340	    ctx.clearRect(0, 0, W, H);
341	    drawBricks();
342	    drawPaddle();
343	    drawBall();
344	
345	    if (state === STATE.READY)
346	      drawOverlay("BALL READY", "space or click to launch");
347	    else if (state === STATE.PAUSED)
348	      drawOverlay("PAUSED", "space to resume");
349	    else if (state === STATE.GAME_OVER)
350	      drawOverlay("GAME OVER", `score ${score} — space or click to restart`);
351	    else if (state === STATE.WIN)
352	      drawOverlay("YOU WIN", "space or click to play again");
353	  }
354	
355	  // --- main loop ----------------------------------------------------------------
356	  let lastTime = 0;
357	  function frame(t) {
358	    const dt = Math.min((t - lastTime) / 1000, 0.033); // clamp to avoid tunneling after tab-switch
359	    lastTime = t;
360	
361	    if (state === STATE.PLAYING) {
362	      movePaddle(dt);
363	      moveBall(dt);
364	      if (state === STATE.PLAYING) checkLevelClear();
365	    } else if (state === STATE.READY) {
366	      movePaddle(dt);
367	    }
368	
369	    render();
370	    requestAnimationFrame(frame);
371	  }
372	
373	  newGame();
374	  requestAnimationFrame((t) => { lastTime = t; requestAnimationFrame(frame); });
375	})();
376	</script>
377	
378	</body>
379	</html>

